async function annotateSearchTool() {
  try {
    const c = await Promise.race([
      ctx(),
      new Promise((_, rej) => setTimeout(() => rej(new Error("timeout")), 8e3))
    ]);
    const { engines } = await tryListSearchEngines(c);
    if (engines.length === 0) return;
    const listed = engines.slice(0, 10).map((e2) => `${e2.displayName} (${e2.id})`).join(", ");
    searchTool.update({
      description: `${SEARCH_DESCRIPTION} Available search apps in this project: ${listed}.`
    });
  } catch {
  }
}
async function main() {
  if (process.argv[2] === "--cli") {
    process.exitCode = await runCli(process.argv.slice(3));
    return;
  }
  try {
    const r2 = JobService.for(loadConfig()).startup(loadConfig());
    if (r2.failed.length || r2.resumed.length) {
      process.stderr.write(`jobs: ${r2.failed.length} marked failed after restart, ${r2.resumed.length} batch job(s) resumed
`);
    }
  } catch {
  }
  const transport = new StdioServerTransport();
  await server.connect(transport);
  process.stderr.write(`gemini-studio-mcp ${VERSION} ready (session ${SERVER_SESSION_ID})
`);
  void annotateSearchTool();
}
main().catch((e2) => {
  process.stderr.write(`gemini-studio-mcp failed to start: ${String(e2)}
`);
  process.exit(1);
});
